async () => {
const out = {};
const npc = () => window.npcManager.getNPC('caller_basic');
document.querySelector('#minigame-close').click();                       // End call while its choices show
await new Promise(r => setTimeout(r, 800));
out.afterEnd = { mg: window.MinigameFramework.currentMinigame?._sceneType || null, state: window.phoneRinger.stateOf('caller_basic'), callActive: window.phoneRinger.callActive(), knot: (JSON.parse(npc().storyState.json || npc().storyState)?.currentFlowName) || null, keys: Object.keys(npc().storyState || {}) };
out.failed = window.eventDispatcher.__failed || null;
window.eventDispatcher.emit('ring_again', {});
await new Promise(r => setTimeout(r, 12500));
document.querySelector('#phone-ring-layer .incoming-call-answer').click();
await new Promise(r => setTimeout(r, 3500));
const m = window.MinigameFramework.currentMinigame;
out.slow = { mg: m?._sceneType, text: document.querySelector('.minigame-container')?.innerText.slice(0, 200) };
return out;

}
